@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#eef3ed;--muted:#91a19a;--lime:#c8f169;--orange:#ff875e;--panel:rgba(14,22,23,.84);--line:rgba(232,244,232,.16)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101619;color:var(--ink);font-family:Manrope,Arial,sans-serif;touch-action:none}#game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#1a2522}canvas#game{display:block;width:100%;height:100%;image-rendering:auto}.topbar{position:absolute;inset:0 0 auto;height:76px;padding:15px 26px;display:flex;align-items:center;gap:32px;background:linear-gradient(180deg,rgba(8,15,16,.9),rgba(8,15,16,.46),transparent);pointer-events:none}.brand{display:flex;align-items:center;gap:10px;min-width:236px}.brand-mark{width:37px;height:37px;display:grid;place-items:center;background:var(--lime);color:#14201b;font:900 25px 'Barlow Condensed';transform:skew(-6deg)}.brand strong{display:block;font:800 16px 'Barlow Condensed';letter-spacing:1.6px}.brand small{display:block;font:9px 'DM Mono';letter-spacing:1.5px;color:#95a59c;margin-top:3px}.district-tag{display:flex;align-items:center;gap:8px;font:500 10px 'DM Mono';letter-spacing:1.6px;color:#d9e2d9}.district-tag i{width:6px;height:6px;background:var(--lime);border-radius:50%;box-shadow:0 0 10px var(--lime)}.status{margin-left:auto;display:flex;gap:18px;align-items:center;font:11px 'DM Mono';letter-spacing:1px;color:#c7d0c8}.clock{font-size:13px;color:#f5f4dd}.weather{color:#a7b5ac}.mission-card,.wanted-card,.map-card{background:var(--panel);border:1px solid var(--line);backdrop-filter:blur(8px);box-shadow:0 8px 26px #05090955}.mission-card{position:absolute;top:88px;left:25px;width:263px;padding:15px 17px 13px;border-left:3px solid var(--lime)}.mission-kicker{font:10px 'DM Mono';letter-spacing:1.4px;color:var(--lime);display:flex;align-items:center;gap:7px}.pulse{width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 7px var(--lime)}#mission-title{font:700 19px 'Barlow Condensed';margin-top:7px;letter-spacing:.3px}.mission-card p{font-size:10px;line-height:1.55;color:#aab8af;margin:5px 0 10px}.mission-footer{display:flex;justify-content:space-between;border-top:1px solid #ffffff19;padding-top:8px;font:9px 'DM Mono';letter-spacing:.7px;color:#9aa99f}.mission-footer b{color:#eaf1de}.right-stack{position:absolute;right:24px;top:90px;display:flex;flex-direction:column;align-items:flex-end;gap:10px}.wanted-card{padding:9px 13px;display:flex;align-items:center;gap:14px}.wanted-card .label{font:9px 'DM Mono';letter-spacing:1px;color:#a4b0a7}.wanted-card #stars{font-size:17px;letter-spacing:3px;color:#ffb66d}.map-card{padding:5px 5px 4px;position:relative}.map-card canvas{width:180px;height:140px;display:block}.map-label{position:absolute;bottom:7px;left:10px;background:#121b1bdc;padding:3px 5px;font:8px 'DM Mono';letter-spacing:1px;color:#c8d3c8}.bottom-left{position:absolute;bottom:20px;left:25px;min-width:340px;padding:12px 15px 10px;background:linear-gradient(90deg,rgba(12,19,19,.9),rgba(12,19,19,.58));border-left:2px solid #c8f169aa}.health-row{display:flex;align-items:center;gap:9px;font:9px 'DM Mono';letter-spacing:1px;color:#aab7ac}.bar{height:5px;width:155px;background:#ffffff25;overflow:hidden}.bar i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#c8f169,#e4ed8c);transition:width .2s}.health-row b{font-weight:500;color:#e6eee2}.cash-row{display:flex;align-items:baseline;gap:6px;margin:6px 0}.cash-symbol{font:700 16px 'Barlow Condensed';color:var(--lime)}.cash-row strong{font:700 23px 'Barlow Condensed';letter-spacing:.6px}.rep{margin-left:12px;font:9px 'DM Mono';color:#819187;letter-spacing:.8px}.rep b{color:#d8e2d3;font-weight:500}.weapon-row{display:flex;align-items:center;gap:7px;color:#a9b5aa;font:9px 'DM Mono';letter-spacing:1px}.weapon-icon{font-size:14px;color:var(--lime)}.weapon-row b{color:#e5e9dd;font-weight:500;margin-left:auto}.hint{margin-left:10px;color:#76857a;font-size:8px;letter-spacing:.3px}.toast{position:absolute;bottom:28px;left:50%;transform:translate(-50%,14px);opacity:0;background:#111b1beF;border:1px solid #c8f16988;padding:11px 18px;font:11px 'DM Mono';letter-spacing:.5px;color:#eaf1dc;transition:.25s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.interact-prompt{position:absolute;left:50%;top:58%;transform:translate(-50%,-50%);font:10px 'DM Mono';letter-spacing:1px;color:#e4eddd;background:#111b1ddd;padding:8px 12px;border:1px solid #ffffff2a;display:none}.interact-prompt b{color:var(--lime)}.start-screen{position:absolute;inset:0;display:flex;align-items:center;background:linear-gradient(90deg,rgba(8,14,15,.92) 0%,rgba(8,14,15,.7) 47%,rgba(8,14,15,.15) 100%);transition:opacity .55s,visibility .55s}.start-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-content{margin-left:11vw;margin-top:-3vh}.eyebrow{font:10px 'DM Mono';letter-spacing:2px;color:var(--lime)}h1{font:900 clamp(68px,10vw,128px)/.8 'Barlow Condensed';letter-spacing:-2px;margin:20px 0 17px;text-shadow:0 10px 40px #0008}h1 em{font-style:normal;color:var(--lime)}.start-content p{color:#c0cbc1;font-size:13px;letter-spacing:.2px;margin:0 0 25px}.start-content button{border:0;background:var(--lime);color:#14201b;padding:15px 21px;font:800 12px 'Barlow Condensed';letter-spacing:1.3px;cursor:pointer;box-shadow:5px 5px 0 #677e3d}.start-content button span{font-size:17px;margin-left:24px}.start-foot{margin-top:39px;font:9px 'DM Mono';letter-spacing:.7px;color:#8f9b91}.start-side{position:absolute;left:65%;top:23%;height:56%;display:flex;flex-direction:column;align-items:flex-start;color:#dce7dc}.big-number{font:900 70px/.9 'Barlow Condensed';color:#d4ef8b}.side-line{height:1px;width:100px;background:#d4ef8b;margin:14px 0}.start-side>span{font:700 12px/1.5 'Barlow Condensed';letter-spacing:2px}.side-coords{position:absolute;bottom:0;font:9px/1.8 'DM Mono';letter-spacing:1px;color:#8f9e94}.pause-badge{display:none;position:absolute;left:50%;top:44%;transform:translate(-50%,-50%);font:800 36px 'Barlow Condensed';letter-spacing:3px;background:#111c1ddf;padding:20px 34px;border:1px solid #c8f169}.pause-badge span{display:block;text-align:center;font:9px 'DM Mono';letter-spacing:1px;color:#abb7ad;margin-top:8px}.pause-badge.show{display:block}.touch-ui{display:none;position:absolute;inset:0;pointer-events:none}.stick-zone{position:absolute;bottom:28px;left:25px;width:132px;height:132px;border-radius:50%;background:#101a1a66;border:1px solid #ffffff3b;pointer-events:auto;touch-action:none}.stick{position:absolute;width:55px;height:55px;left:38px;top:38px;border-radius:50%;background:#c8f169bb;border:2px solid #edffb8;box-shadow:0 3px 12px #0008}.touch-actions{position:absolute;bottom:26px;right:20px;display:flex;gap:8px;align-items:flex-end;pointer-events:auto}.touch-actions button{width:55px;height:55px;border-radius:50%;border:1px solid #d6ef9b88;background:#14201bd9;color:#e9f2df;font:700 9px 'DM Mono';touch-action:none}.touch-actions #touch-fire{width:68px;height:68px;background:#c8f169dd;color:#14201b}.mobile-tip{display:none;position:absolute;bottom:170px;left:50%;transform:translateX(-50%);background:#121c1bbf;padding:6px 9px;font:8px 'DM Mono';color:#d4dfd4;white-space:nowrap}
@media(max-width:700px){.topbar{height:60px;padding:10px 12px;gap:10px}.brand{min-width:0;gap:7px}.brand-mark{width:31px;height:31px;font-size:21px}.brand strong{font-size:13px}.brand small{font-size:7px}.district-tag{font-size:8px;letter-spacing:.8px}.status{gap:7px;font-size:9px}.weather{display:none}.mission-card{top:68px;left:10px;width:203px;padding:10px 12px}.mission-kicker{font-size:8px}#mission-title{font-size:16px}.mission-card p{font-size:9px;margin:4px 0 7px}.mission-footer{font-size:8px;padding-top:6px}.right-stack{top:68px;right:10px;gap:6px}.wanted-card{padding:6px 8px;gap:7px}.wanted-card .label{font-size:8px}.wanted-card #stars{font-size:13px;letter-spacing:1px}.map-card{padding:3px}.map-card canvas{width:112px;height:88px}.map-label{font-size:6px;bottom:4px;left:5px}.bottom-left{left:10px;bottom:13px;min-width:0;padding:8px 10px}.health-row{font-size:8px}.bar{width:90px;height:4px}.cash-row{margin:3px 0}.cash-row strong{font-size:19px}.rep{font-size:8px}.weapon-row{font-size:8px}.hint{display:none}.touch-ui{display:block}.mobile-tip{display:block}.start-content{margin-left:9vw}.start-foot{max-width:230px;font-size:8px;line-height:1.8}.start-side{left:70%;top:29%}.big-number{font-size:54px}.start-side>span{font-size:10px}.start-content p{font-size:11px;max-width:230px}.start-content button{padding:13px 15px}.toast{bottom:165px;font-size:9px;max-width:90vw;white-space:normal;text-align:center}.interact-prompt{top:62%;font-size:9px}}
@media(max-height:500px) and (orientation:landscape){.mission-card{top:65px}.right-stack{top:65px}.bottom-left{bottom:8px}.start-content{margin-top:0}.start-side{top:16%;height:65%}.start-foot{margin-top:20px}.touch-actions{bottom:12px}.stick-zone{bottom:12px}}

(()=>{
'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),mini=document.querySelector('#minimap'),mctx=mini.getContext('2d');
const ui={district:document.querySelector('#district'),clock:document.querySelector('#clock'),weather:document.querySelector('#weather'),title:document.querySelector('#mission-title'),copy:document.querySelector('#mission-copy'),reward:document.querySelector('#mission-reward'),step:document.querySelector('#mission-step'),stars:document.querySelector('#stars'),health:document.querySelector('#health-fill'),healthv:document.querySelector('#health-value'),cash:document.querySelector('#cash'),rep:document.querySelector('#rep'),ammo:document.querySelector('#ammo'),hint:document.querySelector('#control-hint'),toast:document.querySelector('#toast'),prompt:document.querySelector('#prompt'),start:document.querySelector('#start-screen'),pause:document.querySelector('#pause-badge')};
const W=2800,H=2400,ROAD=108,STEP=400,TAU=Math.PI*2;
let vw=innerWidth,vh=innerHeight,dpr=1,camera={x:0,y:0},last=0,gameOn=false,paused=false,elapsed=0,day=20.67,weather=0,toastTimer=0,shootCD=0;
function resize(){dpr=Math.min(devicePixelRatio||1,2);vw=innerWidth;vh=innerHeight;canvas.width=Math.floor(vw*dpr);canvas.height=Math.floor(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
const keys=new Set(),touch={x:0,y:0,run:false,fire:false},pointer={x:vw/2,y:vh/2,down:false};
addEventListener('keydown',e=>{keys.add(e.key.toLowerCase());if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(e.key.toLowerCase()))e.preventDefault();if(e.key.toLowerCase()==='p'&&gameOn&&!e.repeat){paused=!paused;ui.pause.classList.toggle('show',paused)}if(e.key.toLowerCase()==='e'&&gameOn)interact();if(e.key.toLowerCase()==='r'&&player.health<=0)respawn()});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=e.clientX-r.left;pointer.y=e.clientY-r.top});canvas.addEventListener('pointerdown',e=>{pointer.down=true;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerup',()=>pointer.down=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());
const rnd=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),choice=a=>a[Math.floor(Math.random()*a.length)];
let buildings=[],decor=[],cars=[],peds=[],bullets=[],pickups=[],particles=[],police=[],solids=[];
const districts=[{name:'OLD TOWN',x:0,y:0,color:'#6e8576',accent:'#d1a96a'},{name:'GLASS QUARTER',x:1400,y:0,color:'#718495',accent:'#9dd4cc'},{name:'IRONWORKS',x:0,y:1200,color:'#8b735e',accent:'#e7a65c'},{name:'SUNSET ROW',x:1400,y:1200,color:'#967567',accent:'#f1a173'},{name:'THE UNDERLINE',x:900,y:900,color:'#716b83',accent:'#cf83dc'}];
const palettes={
 'OLD TOWN':['#536b5d','#627766','#718775','#796d58','#65795f'],
 'GLASS QUARTER':['#536574','#607986','#728997','#5d6b7b','#82919a'],
 'IRONWORKS':['#725e4c','#806b52','#65594e','#8b704f','#67645a'],
 'SUNSET ROW':['#886e5c','#9a7660','#a38368','#716657','#927c63'],
 'THE UNDERLINE':['#605c70','#716b7b','#5b6673','#807385','#626174']};
function districtAt(x,y){if(x>1150&&y<1050)return districts[1];if(y>1120&&x<1300)return districts[2];if(x>1350&&y>1150)return districts[3];if(x>750&&x<1450&&y>750&&y<1450)return districts[4];return districts[0]}
function addBuilding(x,y,w,h,kind='block') {const d=districtAt(x,y),palette=palettes[d.name];let b={x,y,w,h,kind,district:d.name,color:choice(palette),roof:choice(['#293532','#303a39','#394241','#343d3a']),seed:Math.random()*1000,sign:kind==='shop'?choice(['DINER','MOTEL','MARKET','LAUNDROMAT','NIGHT OWL']):null,windows:[]};for(let wx=x+14;wx<x+w-10;wx+=24)for(let wy=y+14;wy<y+h-8;wy+=22)b.windows.push({x:wx,y:wy,on:Math.random()>.3});buildings.push(b);solids.push({x,y,w,h,ref:b})}
function generateCity(){
 // Build varied city blocks with alleys and little courtyards, leaving connected streets open.
 for(let gy=-1;gy<6;gy++)for(let gx=-1;gx<7;gx++){let bx=gx*STEP+ROAD/2+8,by=gy*STEP+ROAD/2+8,bw=STEP-ROAD-16,bh=STEP-ROAD-16;if(bx<0||by<0||bx+bw>W||by+bh>H)continue;let d=districtAt(bx,by),tower=d.name==='GLASS QUARTER';
   if(Math.random()<.16){addBuilding(bx+20,by+20,bw-40,bh-40,tower?'tower':'block');continue}
   let alley=20,cols=Math.random()<.45?2:3,rows=Math.random()<.48?2:3,cw=(bw-alley*(cols+1))/cols,ch=(bh-alley*(rows+1))/rows;
   for(let ix=0;ix<cols;ix++)for(let iy=0;iy<rows;iy++){let x=bx+alley+(cw+alley)*ix,y=by+alley+(ch+alley)*iy,w=cw-rnd(3,13),h=ch-rnd(3,13);if(Math.random()<.14)continue;let shop=d.name==='SUNSET ROW'||d.name==='OLD TOWN';addBuilding(x,y,w,h,shop&&Math.random()<.24?'shop':tower&&Math.random()<.5?'tower':'block')}
 }
 // Distinct recognizable landmarks (locations are deliberately kept clear of the main roads).
 addBuilding(1240,260,175,105,'landmark');buildings.at(-1).sign='AURORA HOTEL';
 addBuilding(1860,700,160,130,'landmark');buildings.at(-1).sign='CIVIC PLAZA';
 addBuilding(300,1620,200,125,'landmark');buildings.at(-1).sign='MERCY DEPOT';
 addBuilding(1820,1740,165,100,'landmark');buildings.at(-1).sign='LUCKY STAR';
 // Draw-ready curbside details, trees, hydrants, lamps and dumpsters.
 for(let i=0;i<230;i++){let x=rnd(30,W-30),y=rnd(30,H-30);if(nearRoad(x,y,28))continue;let blocked=solids.some(b=>x>b.x-12&&x<b.x+b.w+12&&y>b.y-12&&y<b.y+b.h+12);if(!blocked)decor.push({x,y,type:Math.random()<.68?'tree':choice(['lamp','dumpster','hydrant','bench']),seed:Math.random()})}
}
function nearRoad(x,y,pad=0){let vx=((x%STEP)+STEP)%STEP,vy=((y%STEP)+STEP)%STEP;return Math.min(vx,STEP-vx)<ROAD/2+pad||Math.min(vy,STEP-vy)<ROAD/2+pad}
generateCity();
const player={x:STEP/2,y:STEP/2+40,vx:0,vy:0,r:11,angle:0,health:100,cash:1250,rep:0,wanted:0,weapon:'SIDEARM',inCar:null,invuln:0,anim:0};
const carColors=['#d78550','#82b875','#638ec1','#d4c36e','#c45c59','#c2d0c4','#ac7cb1','#4eb0a3','#df905f'];
function makeCar(x,y,angle,type){let spec=type==='van'?{max:210,acc:300,turn:2.1,hp:135}:{max:275,acc:390,turn:2.7,hp:100};let c={x,y,angle,speed:0,length:type==='van'?43:37,width:type==='van'?21:18,type:type||'sedan',color:choice(carColors),hp:spec.hp,max:spec.max,acc:spec.acc,turn:spec.turn,occupied:false,police:false,seed:Math.random()*20,driver:Math.random()};cars.push(c);return c}
function seedCars(){for(let i=0;i<26;i++){let vertical=Math.random()<.5,x,y,a;if(vertical){let lane=Math.floor(rnd(0,7))*STEP+(Math.random()<.5?-18:18);x=clamp(lane,40,W-40);y=rnd(40,H-40);a=Math.PI/2}else{y=clamp(Math.floor(rnd(0,6))*STEP+(Math.random()<.5?-18:18),40,H-40);x=rnd(40,W-40);a=0}let c=makeCar(x,y,a,Math.random()<.12?'van':'sedan');c.speed=rnd(25,75)}for(let i=0;i<75;i++){let x,y;do{x=rnd(40,W-40);y=rnd(40,H-40)}while(!nearRoad(x,y,-4));peds.push({x,y,angle:rnd(0,TAU),speed:rnd(12,26),color:choice(['#e4b080','#cf7d6e','#8bb7a1','#b9a2d4','#d5d9c6']),panic:0,alive:true})}}
seedCars();
function spawnPickups(){for(let i=0;i<22;i++){let x,y;do{x=rnd(50,W-50);y=rnd(50,H-50)}while(solids.some(b=>x>b.x-15&&x<b.x+b.w+15&&y>b.y-15&&y<b.y+b.h+15));pickups.push({x,y,type:Math.random()<.55?'cash':'health',value:Math.random()<.3?250:100,phase:rnd(0,TAU)})}}spawnPickups();
const missions=[{title:'A favor for Frankie',copy:'Meet Frankie by the payphone in Old Town.',reward:450,type:'contact',x:740,y:370},{title:'Midnight delivery',copy:'Take the package to the Lucky Star in Sunset Row.',reward:850,type:'drive',x:1880,y:1790},{title:'Make some noise',copy:'Put 3 rival troublemakers on the run.',reward:1200,type:'chaos',goal:3}];let missionIndex=0,missionProgress=0,missionActive=false;
function updateMissionUI(){if(missionIndex>=missions.length){ui.title.textContent='City legend';ui.copy.textContent='No contracts. The whole city is your playground.';ui.reward.innerHTML='STATUS <b>FREE ROAM</b>';ui.step.textContent='03 / 03';return}let m=missions[missionIndex];ui.title.textContent=m.title;ui.copy.textContent=missionActive?(m.type==='contact'?'Frankie is waiting nearby. Walk up and press E.':m.type==='drive'?'Bring your ride to the drop marker.':'Cause a little chaos around the city — evade the heat.') :m.copy;ui.reward.innerHTML='REWARD <b>$'+m.reward.toLocaleString()+'</b>';ui.step.textContent=String(missionIndex+1).padStart(2,'0')+' / 03'}updateMissionUI();

input.newString:
updateMissionUI();
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.5}
function startGame(){gameOn=true;ui.start.classList.add('hidden');showToast('Welcome to Neon Harbor. Frankie has a line on you.');last=performance.now();requestAnimationFrame(loop)}document.querySelector('#start-button').addEventListener('click',startGame);
function activeTarget(){if(missionIndex>=missions.length)return null;let m=missions[missionIndex];return m.type==='chaos'?null:{x:m.x,y:m.y}}
function nearestCar(){let best=null,bd=62;for(const c of cars){if(c.occupied)continue;let d=Math.hypot(c.x-player.x,c.y-player.y);if(d<bd){bd=d;best=c}}return best}
function interact(){if(player.health<=0)return;let car=nearestCar();if(player.inCar){let c=player.inCar,ex=c.x+Math.cos(c.angle+Math.PI/2)*28,ey=c.y+Math.sin(c.angle+Math.PI/2)*28;if(!blocked(ex,ey,player.r)){player.x=ex;player.y=ey;player.inCar=null;c.occupied=false;c.speed*=.35;player.vx=player.vy=0;showToast('Back on foot. Keep moving.')}return}if(car){car.occupied=true;player.inCar=car;player.x=car.x;player.y=car.y;player.angle=car.angle;player.wanted=Math.min(5,player.wanted+1);showToast('Vehicle acquired · Heat is rising');return}
 const m=missions[missionIndex];if(m&&missionActive&&m.type==='contact'&&Math.hypot(player.x-m.x,player.y-m.y)<90){completeMission();return}
 // Interact with businesses and street pickups.
 let b=buildings.find(b=>b.sign&&Math.hypot(player.x-(b.x+b.w/2),player.y-(b.y+b.h/2))<Math.max(b.w,b.h)/2+38);if(b){if(b.sign==='GUN SHOP'){if(player.cash>=300){player.cash-=300;player.weapon='BURST';showToast('Burst sidearm purchased · $300')}else showToast('Need $300 for the burst sidearm')}else if(b.sign==='GARAGE'){if(player.inCar){player.inCar.hp=100;player.inCar.color='#c8f169';player.cash=Math.max(0,player.cash-150);showToast('Ride repaired · $150')}else showToast('Bring a vehicle to the garage')}else showToast(b.sign+' · Open late, ask no questions');return}
 showToast('Nothing close enough to interact with.')}
function completeMission(){let m=missions[missionIndex];player.cash+=m.reward;player.rep+=Math.round(m.reward/50);player.wanted=Math.max(0,player.wanted-1);missionIndex++;missionActive=false;missionProgress=0;updateMissionUI();showToast('Contract complete · +$'+m.reward+' · Reputation up');}
function activateMission(){if(missionIndex>=missions.length){showToast('No active contracts. Explore the city.');return}if(!missionActive){missionActive=true;updateMissionUI();showToast('Contract accepted · Check your map marker');return}let m=missions[missionIndex];if(m.type==='chaos'){showToast('Rival troublemakers marked in red. Stay sharp.');return}if(m.type==='contact'&&Math.hypot(player.x-m.x,player.y-m.y)<90){completeMission();return}if(m.type==='drive'&&Math.hypot(player.x-m.x,player.y-m.y)<100&&player.inCar){completeMission();return}showToast('Follow the marker on your map.')}
