-:root{--ink:#eef3ed;--muted:#91a19a;--lime:#c8f169;--orange:#ff875e;--panel:rgba(14,22,23,.84);--line:rgba(232,244,232,.16)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101619;color:var(--ink);font-family:Manrope,Arial,sans-serif;touch-action:none}#game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#1a2522}canvas#game{display:block;width:100%;height:100%;image-rendering:auto}.topbar{position:absolute;inset:0 0 auto;height:76px;padding:15px 26px;display:flex;align-items:center;gap:32px;background:linear-gradient(180deg,rgba(8,15,16,.9),rgba(8,15,16,.46),transparent);pointer-events:none}.brand{display:flex;align-items:center;gap:10px;min-width:236px}.brand-mark{width:37px;height:37px;display:grid;place-items:center;background:var(--lime);color:#14201b;font:900 25px 'Barlow Condensed';transform:skew(-6deg)}.brand strong{display:block;font:800 16px 'Barlow Condensed';letter-spacing:1.6px}.brand small{display:block;font:9px 'DM Mono';letter-spacing:1.5px;color:#95a59c;margin-top:3px}.district-tag{display:flex;align-items:center;gap:8px;font:500 10px 'DM Mono';letter-spacing:1.6px;color:#d9e2d9}.district-tag i{width:6px;height:6px;background:var(--lime);border-radius:50%;box-shadow:0 0 10px var(--lime)}.status{margin-left:auto;display:flex;gap:18px;align-items:center;font:11px 'DM Mono';letter-spacing:1px;color:#c7d0c8}.clock{font-size:13px;color:#f5f4dd}.weather{color:#a7b5ac}.mission-card,.wanted-card,.map-card{background:var(--panel);border:1px solid var(--line);backdrop-filter:blur(8px);box-shadow:0 8px 26px #05090955}.mission-card{position:absolute;top:88px;left:25px;width:263px;padding:15px 17px 13px;border-left:3px solid var(--lime)}.mission-kicker{font:10px 'DM Mono';letter-spacing:1.4px;color:var(--lime);display:flex;align-items:center;gap:7px}.pulse{width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 7px var(--lime)}#mission-title{font:700 19px 'Barlow Conde